function Nx.ModQuests:Load6()
    local ModQuests = Nx.ModQuests:Data6()
    local count = 0
    for key, val in pairs(ModQuests) do
        Nx.Quests[key] = val
        count = count + 1
    end
    ModQuests = {}
    return count
end

function Nx.ModQuests:Clear6()
    --ModQuests = {}
end
